package com.battlemanson.codekanban;

import org.json.*;

public final class AutomationEngineTest {
    static final long HOUR=3600000L,NOW=2_000_000_000_000L;
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    static JSONObject card(JSONObject data)throws Exception{return data.getJSONArray("boards").getJSONObject(0).getJSONArray("columns").getJSONObject(0).getJSONArray("cards").getJSONObject(0);}
    static JSONObject fixture()throws Exception{
        JSONObject card=new JSONObject().put("id","item").put("title","Urgent story").put("createdAt",NOW-48*HOUR).put("columnEnteredAt",NOW-12*HOUR).put("tasks",new JSONArray().put(new JSONObject().put("id","t1").put("done",false)).put(new JSONObject().put("id","t2").put("done",false)));
        return new JSONObject().put("boards",new JSONArray().put(new JSONObject().put("id","board").put("columns",new JSONArray().put(new JSONObject().put("id","todo").put("name","To Do").put("cards",new JSONArray().put(card))).put(new JSONObject().put("id","done").put("name","Done").put("cards",new JSONArray()))))).put("automations",new JSONArray());
    }
    static JSONObject condition(String field,String op,String value)throws Exception{return new JSONObject().put("field",field).put("op",op).put("value",value);}
    static JSONObject action(String type,String value)throws Exception{return new JSONObject().put("type",type).put("value",value);}
    static JSONObject rule(String trigger,JSONArray conditions,JSONArray actions)throws Exception{return new JSONObject().put("id","rule").put("name","Test rule").put("enabled",true).put("boardId","").put("trigger",trigger).put("match","all").put("conditions",conditions).put("actions",actions);}
    static JSONObject move(JSONObject data)throws Exception{JSONArray cols=data.getJSONArray("boards").getJSONObject(0).getJSONArray("columns");JSONObject item=cols.getJSONObject(0).getJSONArray("cards").getJSONObject(0);cols.getJSONObject(0).getJSONArray("cards").remove(0);cols.getJSONObject(1).getJSONArray("cards").put(item);return item;}
    public static void main(String[] args)throws Exception{
        JSONObject data=fixture(),baseline=BoardTemplate.copy(data);
        data.getJSONArray("automations").put(rule("moved",new JSONArray().put(condition("column","eq","Done")),new JSONArray().put(action("completeTasks","")).put(action("reminder","60"))));
        JSONObject moved=move(data);AutomationEngine.run(data,baseline,NOW,"device-one");
        check(moved.getJSONArray("tasks").getJSONObject(0).getBoolean("done")&&moved.getJSONArray("tasks").getJSONObject(1).getBoolean("done"),"Moving completes all tasks");
        JSONObject reminder=moved.getJSONArray("reminders").getJSONObject(0);check(reminder.getLong("at")==NOW+HOUR,"Relative reminder delay");check("device-one".equals(reminder.getString("originDeviceId")),"Automated reminder uses executing device");
        check(moved.getLong("columnEnteredAt")==NOW,"Move resets column age");
        baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW+60000,"device-one");check(moved.getJSONArray("reminders").length()==1,"Saving again does not replay move event");
        data=fixture();baseline=BoardTemplate.copy(data);JSONObject age=rule("conditions",new JSONArray().put(condition("ageHours","gte","48")),new JSONArray().put(action("color","#EF4444")).put(action("reminder","10")));data.getJSONArray("automations").put(age);
        AutomationEngine.run(data,baseline,NOW-1,"device");check(!card(data).has("automationColor"),"Age threshold is not early");
        baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW,"device");check("#EF4444".equals(card(data).getString("automationColor")),"Age threshold colors card");
        baseline=BoardTemplate.copy(data);check(!AutomationEngine.run(data,baseline,NOW+60000,"device"),"No writes or duplicate reminders every minute");check(card(data).getJSONArray("reminders").length()==1,"Condition reminder fires only once");
        card(data).put("createdAt",NOW+100*HOUR);baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW+2*HOUR,"device");card(data).put("createdAt",NOW-48*HOUR);baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW+3*HOUR,"device");check(card(data).getJSONArray("reminders").length()==2,"Leaving and re-entering conditions permits another run");
        data=fixture();baseline=BoardTemplate.copy(data);JSONObject scoped=rule("conditions",new JSONArray(),new JSONArray().put(action("color","#000000"))).put("boardId","another-board");data.getJSONArray("automations").put(scoped);AutomationEngine.run(data,baseline,NOW,"device");check(!card(data).has("automationColor"),"Board scope respected");
        scoped.put("boardId","").put("enabled",false);baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW,"device");check(!card(data).has("automationColor"),"Disabled rule does not execute");
        scoped.put("enabled",true).put("conditions",new JSONArray().put(condition("title","contains","absent")).put(condition("title","contains","urgent"))).put("match","any");baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW,"device");check(card(data).has("automationColor"),"Any condition supports case-insensitive text");
        data=fixture();baseline=BoardTemplate.copy(data);data.getJSONArray("automations").put(rule("updated",new JSONArray(),new JSONArray().put(action("label","review"))));card(data).put("title","Changed");AutomationEngine.run(data,baseline,NOW,"device");check(card(data).getString("labels").equals("review"),"Edit event executes actions");baseline=BoardTemplate.copy(data);AutomationEngine.run(data,baseline,NOW+HOUR,"device");check(data.getJSONArray("automations").getJSONObject(0).getLong("runCount")==1,"No recursive update loop");
        data=fixture();baseline=BoardTemplate.copy(data);data.getJSONArray("automations").put(rule("created",new JSONArray(),new JSONArray().put(action("priority","1"))));JSONObject fresh=new JSONObject().put("id","new").put("title","New item");data.getJSONArray("boards").getJSONObject(0).getJSONArray("columns").getJSONObject(0).getJSONArray("cards").put(fresh);AutomationEngine.run(data,baseline,NOW,"device");check(fresh.optString("priority").equals("1")&&!card(data).has("priority"),"Created trigger excludes existing items");
        data=fixture();JSONObject liveCard=card(data),liveTask=liveCard.getJSONArray("tasks").getJSONObject(0);JSONObject draft=BoardTemplate.copy(data);card(draft).getJSONArray("tasks").getJSONObject(0).put("done",true);card(draft).put("automationColor","#123456");check(!liveTask.optBoolean("done"),"Evaluation draft leaves unsaved state unchanged");AutomationEngine.adopt(data,draft);check(liveCard==card(data)&&liveTask==card(data).getJSONArray("tasks").getJSONObject(0)&&liveTask.optBoolean("done"),"Successful save preserves live object identity");
        JSONObject invalid=rule("conditions",new JSONArray().put(condition("ageHours","gte","NaN")),new JSONArray().put(action("color","red")));boolean rejected=false;try{AutomationEngine.validate(invalid);}catch(JSONException e){rejected=true;}check(rejected,"Invalid rule values rejected");
        data=fixture();card(data).remove("createdAt");card(data).remove("columnEnteredAt");AutomationEngine.initialize(data,NOW);check(card(data).getLong("createdAt")==NOW,"Legacy age starts at migration");
        data=fixture();baseline=BoardTemplate.copy(data);data.getJSONArray("automations").put(rule("moved",new JSONArray().put(condition("previousColumn","eq","To Do")),new JSONArray().put(action("label","moved"))));
        JSONObject another=new JSONObject().put("id","second").put("columns",new JSONArray().put(new JSONObject().put("id","destination").put("name","Ready").put("cards",new JSONArray())));data.getJSONArray("boards").put(another);JSONObject transferred=card(data);data.getJSONArray("boards").getJSONObject(0).getJSONArray("columns").getJSONObject(0).getJSONArray("cards").remove(0);another.getJSONArray("columns").getJSONObject(0).getJSONArray("cards").put(transferred);AutomationEngine.run(data,baseline,NOW,"device");check(transferred.optString("labels").equals("moved"),"Cross-board moves preserve previous-column trigger context");
        data=fixture();baseline=BoardTemplate.copy(data);data.getJSONArray("automations").put(rule("created",new JSONArray(),new JSONArray().put(action("priority","3"))));JSONObject duplicate=BoardTemplate.copy(data.getJSONArray("boards").getJSONObject(0)).put("id","duplicate-board");data.getJSONArray("boards").put(duplicate);AutomationEngine.run(data,baseline,NOW,"device");check(duplicate.getJSONArray("columns").getJSONObject(0).getJSONArray("cards").getJSONObject(0).optString("priority").equals("3"),"Template card IDs in a new board count as creation, not a move");
        System.out.println("Automation event, age, conditions, idempotence, device origin, scope, validation and atomic-draft checks passed.");
    }
}
